Example
For details about the complete call example, see 5.1.31 More Examples.
// The input shape is 1024. The operator input data is of the half type. The source operand cannot be
modified.
std::vector<int64_t> shape_vec = {1024};
ge::Shape shape(shape_vec);
uint32_t maxValue = 0;
uint32_t minValue = 0;
AscendC::GetClampMaxMinTmpSize(shape, 2, false, maxValue, minValue);
